import React from "react";
import styled from "styled-components";
import { Facebook, Twitter, Linkedin } from "lucide-react";

const FooterContainer = styled.footer`
  background: linear-gradient(135deg, #6a11cb 0%, #2575fc 100%);  /* Gradient màu tím và xanh */
  padding: 60px 40px 30px 40px;
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  border-top: 1px solid #e0e0e0;
  color: white;
`;

const LogoSection = styled.div`
  flex: 1.2;
  min-width: 240px;
  margin: 20px;

  img {
    width: 150px;
    margin-bottom: 16px;
  }

  p {
    font-size: 15px;
    color: #ddd;
    max-width: 300px;
    line-height: 1.6;
  }
`;

const Column = styled.div`
  flex: 1;
  min-width: 200px;
  margin: 20px;

  h4 {
    font-size: 18px;
    font-weight: bold;
    margin-bottom: 20px;
    color: #fff;
  }

  ul {
    list-style: none;
    padding: 0;

    li {
      margin-bottom: 12px;
      font-size: 15px;
      color: #ddd;
      cursor: pointer;
      transition: color 0.3s;

      &:hover {
        color: #fff;
      }
    }
  }
`;

const SocialIcons = styled.div`
  display: flex;
  gap: 14px;
  margin-top: 8px;
`;

const IconWrapper = styled.a`
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background-color: ${({ color }) => color || "#ccc"};
  display: flex;
  align-items: center;
  justify-content: center;
  text-decoration: none;

  svg {
    color: white;
    width: 20px;
    height: 20px;
    transition: transform 0.3s ease;
  }

  &:hover svg {
    transform: scale(1.2);
  }
`;

const Copyright = styled.div`
  width: 100%;
  text-align: center;
  margin-top: 40px;
  font-size: 14px;
  color: #ddd;
  border-top: 1px solid #bbb;
  padding-top: 20px;
`;

const Footer = () => {
  return (
    <FooterContainer>
      <LogoSection>
        <img src="/logo.png" alt="Bakta Logo" />
        <p>
          Bakta là nền tảng phân tích dữ liệu sinh học mạnh mẽ, giúp bạn khám phá
          thông tin gen và xây dựng giải pháp vi sinh nhanh chóng và chính xác.
        </p>
      </LogoSection>

      <Column>
        <h4>Về chúng tôi</h4>
        <ul>
          <li>Giới thiệu</li>
          <li>Liên hệ</li>
          <li>Blog</li>
        </ul>
      </Column>

      <Column>
        <h4>Hỗ trợ</h4>
        <ul>
          <li>FAQs</li>
          <li>Chính sách bảo mật</li>
          <li>Điều khoản sử dụng</li>
        </ul>
      </Column>

      <Column>
        <h4>Kết nối với chúng tôi</h4>
        <SocialIcons>
          <IconWrapper href="https://facebook.com" target="_blank" rel="noopener noreferrer" color="#3b5998">
            <Facebook />
          </IconWrapper>
          <IconWrapper href="https://twitter.com" target="_blank" rel="noopener noreferrer" color="#1da1f2">
            <Twitter />
          </IconWrapper>
          <IconWrapper href="https://linkedin.com" target="_blank" rel="noopener noreferrer" color="#0077b5">
            <Linkedin />
          </IconWrapper>
        </SocialIcons>
      </Column>
      <Copyright>© 2025  All rights reserved.</Copyright>
    </FooterContainer>
  );
};

export default Footer;
